    aipl_println(aipl_str_n("  - CLI & I/O: JSON-RPC 2.0 dispatcher, declarative CliApp argument parsing, streaming pipes", 92));
    aipl_println(aipl_str_n("  - Math & DSP: 3D vector & matrix affine transforms, quaternions, Cooley-Tukey radix-2 FFT", 91));
